"""Persistent reservation controller for version 3.0.0 of the protocol.

The controller owns the graph image, the lease book, proposal history and the
revision counter.  Compilation and negative certificates live in compiler.py.
All arithmetic uses Python integers.
"""

import re

import compiler
from compiler import find_deficient_cut

LIM = 10 ** 12
ID_RE = re.compile(r'[A-Za-z0-9_.\-]{1,32}\Z')


class Invalid(Exception):
    pass


# ---------------------------------------------------------------- validation

def _is_int(x):
    return type(x) is int


def _int(x, lo=0, hi=LIM):
    if type(x) is not int or x < lo or x > hi:
        raise Invalid()
    return x


def _name(x):
    if not isinstance(x, str) or not ID_RE.match(x):
        raise Invalid()
    return x


def _window(x):
    if not isinstance(x, list) or len(x) != 2:
        raise Invalid()
    s = _int(x[0])
    e = _int(x[1])
    if not s < e:
        raise Invalid()
    return (s, e)


def _envelope(x):
    if not isinstance(x, list) or len(x) > 128:
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        l = _int(item[0], 0, 127)
        rate = _int(item[1], 1, LIM)
        if l in out:
            raise Invalid()
        out[l] = rate
    return out


def _fields(obj, names):
    if not isinstance(obj, dict):
        raise Invalid()
    if set(obj) != set(names):
        raise Invalid()
    return obj


def _booking(x):
    _fields(x, ('id', 'owner', 'window', 'envelope'))
    ident = _name(x['id'])
    owner = _name(x['owner'])
    win = _window(x['window'])
    env = _envelope(x['envelope'])
    return ident, owner, win, env


def _load_shape(x):
    _fields(x, ('op', 'n', 'links', 'bookings'))
    n = _int(x['n'], 2, 48)
    links = x['links']
    if not isinstance(links, list) or len(links) > 128:
        raise Invalid()
    out = []
    seen = set()
    for item in links:
        if not isinstance(item, list) or len(item) != 3:
            raise Invalid()
        u = _int(item[0], 0, 47)
        v = _int(item[1], 0, 47)
        cap = _int(item[2])
        if u == v or u >= n or v >= n:
            raise Invalid()
        key = (u, v) if u < v else (v, u)
        if key in seen:
            raise Invalid()
        seen.add(key)
        out.append((u, v, cap))
    bookings = x['bookings']
    if not isinstance(bookings, list) or len(bookings) > 128:
        raise Invalid()
    ids = set()
    total = 0
    parsed = []
    for item in bookings:
        ident, owner, win, env = _booking(item)
        if ident in ids:
            raise Invalid()
        ids.add(ident)
        total += len(env)
        for l in env:
            if l >= len(out):
                raise Invalid()
        parsed.append((ident, owner, win, env))
    if total > 2048:
        raise Invalid()
    return n, out, parsed


def _participants(x):
    if not isinstance(x, list) or not (2 <= len(x) <= 32):
        raise Invalid()
    out = {}
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        v = _int(item[0], 0, 47)
        amount = _int(item[1])
        if v in out:
            raise Invalid()
        out[v] = amount
    if sum(out.values()) <= 0:
        raise Invalid()
    return out


def _changes(x):
    if not isinstance(x, list) or len(x) > 128:
        raise Invalid()
    out = []
    seen = set()
    for item in x:
        if not isinstance(item, list) or len(item) != 2:
            raise Invalid()
        l = _int(item[0], 0, 127)
        cap = _int(item[1])
        if l in seen:
            raise Invalid()
        seen.add(l)
        out.append((l, cap))
    return out


def _ticks(x):
    if not isinstance(x, list) or len(x) > 8:
        raise Invalid()
    return [_int(t) for t in x]


def _bool(x):
    if x is True:
        return True
    if x is False:
        return False
    raise Invalid()


# ---------------------------------------------------------------- service

class Service:
    def __init__(self):
        self.loaded = False
        self.rev = 0
        self.time = 0
        self.n = 0
        self.links = []
        self.cap = []
        self.leases = {}          # live committed leases: id -> record
        self.dead = {}            # id -> owner, for expired/cancelled/revoked
        self.preps = {}           # id -> proposal history
        self.load_ids = set()     # ids originating in load

    # ---- small helpers ----
    def _error(self, code):
        return {'status': 'error', 'code': code, 'rev': self.rev}

    def _stale(self):
        return {'status': 'stale', 'rev': self.rev}

    def _not_loaded(self):
        return {'status': 'error', 'code': 'NOT_LOADED', 'rev': 0}

    def used(self, link, t):
        total = 0
        for rec in self.leases.values():
            if rec['s'] <= t < rec['e']:
                total += rec['env'].get(link, 0)
        return total

    def used_vector(self, t):
        vec = [0] * len(self.links)
        for rec in self.leases.values():
            if rec['s'] <= t < rec['e']:
                for l, rate in rec['env'].items():
                    vec[l] += rate
        return vec

    # ---- dispatch ----
    def handle(self, request):
        if not isinstance(request, dict):
            return {'status': 'invalid'}
        op = request.get('op')
        if not isinstance(op, str):
            return {'status': 'invalid'}
        try:
            if op == 'about':
                if set(request) != {'op'}:
                    raise Invalid()
                return {'status': 'ok', 'protocol': 'forest-controller/3'}
            if op == 'load':
                return self.op_load(request)
            if op == 'audit':
                at = _ticks(request.get('at') if 'at' in request else _missing())
                return self._guard('audit', at, lambda: self.op_audit(at))
            if op == 'advance':
                t = _int(request.get('time') if 'time' in request else _missing())
                return self._guard('advance', t, lambda: self.op_advance(t))
            if op == 'edit':
                return self._guard('edit', None, lambda: self.op_edit(request))
            if op == 'prepare':
                return self._guard('prepare', None, lambda: self.op_prepare(request))
            if op == 'commit':
                return self._guard('commit', None, lambda: self.op_commit(request))
            if op == 'cancel':
                return self._guard('cancel', None, lambda: self.op_cancel(request))
        except Invalid:
            return {'status': 'invalid'}
        return {'status': 'invalid'}

    def _guard(self, op, a, body):
        # `a` is unused except to keep the small dispatch closures readable
        return body()

    # ---- operations ----
    def op_load(self, request):
        n, links, bookings = _load_shape(request)
        if self.loaded:
            return {'status': 'error', 'code': 'ALREADY_LOADED', 'rev': self.rev}
        # first load: the initial book must never exceed base capacity
        if not self._book_ok(links, bookings):
            raise Invalid()
        self.loaded = True
        self.n = n
        self.links = links
        self.cap = [cap for (_u, _v, cap) in links]
        self.rev = 0
        self.time = 0
        self.leases = {}
        self.dead = {}
        self.preps = {}
        self.load_ids = set()
        for ident, owner, (s, e), env in bookings:
            self.leases[ident] = {'owner': owner, 's': s, 'e': e, 'env': env}
            self.load_ids.add(ident)
        return {'status': 'ok', 'rev': 0, 'now': 0}

    def _book_ok(self, links, bookings):
        caps = [cap for (_u, _v, cap) in links]
        points = set()
        for (_i, _o, (s, e), _env) in bookings:
            points.add(s)
            points.add(e)
        for t in sorted(points):
            vec = [0] * len(links)
            for (_i, _o, (s, e), env) in bookings:
                if s <= t < e:
                    for l, rate in env.items():
                        vec[l] += rate
            for l, amount in enumerate(vec):
                if amount > caps[l]:
                    return False
        return True

    def op_audit(self, request):
        at = _ticks(request['at'])
        if not self.loaded:
            return self._not_loaded()
        for t in at:
            if t < self.time:
                return self._error('TIME')
        leases = sorted(self.leases)
        samples = []
        for t in at:
            vec = self.used_vector(t)
            samples.append([t, [self.cap[l] - vec[l] for l in range(len(self.links))]])
        return {'status': 'ok', 'rev': self.rev, 'now': self.time,
                'leases': leases, 'samples': samples}

    def op_advance(self, request):
        t = _int(request['time'])
        if not self.loaded:
            return self._not_loaded()
        if t < self.time:
            return self._error('TIME')
        expired = sorted(i for i, rec in self.leases.items() if rec['e'] <= t)
        for i in expired:
            rec = self.leases.pop(i)
            self.dead[i] = rec['owner']
        self.time = t
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'now': t, 'expired': expired}

    def op_edit(self, request):
        _fields(request, ('op', 'rev', 'changes', 'force'))
        changes = _changes(request['changes'])
        force = _bool(request['force'])
        rev = _int(request['rev'])
        if not self.loaded:
            return self._not_loaded()
        if rev != self.rev:
            return self._stale()
        for (l, _c) in changes:
            if l >= len(self.links):
                return self._error('REFERENCE')
        newcap = list(self.cap)
        for (l, c) in changes:
            newcap[l] = c
        if force:
            dec = set()
            for (l, c) in changes:
                if c < self.cap[l]:
                    dec.add(l)
            revoked = []
            for i, rec in list(self.leases.items()):
                if any(rec['env'].get(l, 0) > 0 for l in dec):
                    revoked.append(i)
            for i in revoked:
                rec = self.leases.pop(i)
                self.dead[i] = rec['owner']
            self.cap = newcap
            self.rev += 1
            return {'status': 'ok', 'rev': self.rev, 'cancelled': sorted(revoked)}
        witness = self._overbook(newcap)
        if witness is not None:
            l, t, u, c = witness
            return {'status': 'blocked', 'rev': self.rev, 'link': l,
                    'time': t, 'used': u, 'capacity': c}
        self.cap = newcap
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'cancelled': []}

    def _overbook(self, newcap):
        times = {self.time}
        for rec in self.leases.values():
            if rec['s'] > self.time:
                times.add(rec['s'])
            if rec['e'] > self.time:
                times.add(rec['e'])
        for t in sorted(times):
            if t > self.time and all(rec['e'] <= t for rec in self.leases.values()):
                continue
            vec = self.used_vector(t)
            for l, amount in enumerate(vec):
                if amount > newcap[l]:
                    return (l, t, amount, newcap[l])
        return None

    def op_prepare(self, request):
        _fields(request, ('op', 'id', 'owner', 'window', 'period',
                          'participants', 'envelope', 'rev'))
        ident = _name(request['id'])
        owner = _name(request['owner'])
        window = _window(request['window'])
        period = _int(request['period'], 1, 10 ** 6)
        parts = _participants(request['participants'])
        env = _envelope(request['envelope'])
        rev = _int(request['rev'])
        if not self.loaded:
            return self._not_loaded()
        key = (owner, window, period, frozenset(parts.items()),
               frozenset(env.items()), rev)
        old = self.preps.get(ident)
        if old is not None:
            if old['key'] == key:
                return {'status': 'replay', 'id': ident, 'rev': self.rev,
                        'base_rev': old['base_rev'], 'outcome': old['outcome']}
            return self._error('CONFLICT')
        if ident in self.load_ids:
            return self._error('CONFLICT')
        if rev != self.rev:
            return self._stale()
        for v in parts:
            if v >= self.n:
                return self._error('REFERENCE')
        for l in env:
            if l >= len(self.links):
                return self._error('REFERENCE')
        s, e = window
        if s < self.time:
            return self._error('TIME')
        if (e - s) % period != 0:
            return self._error('WINDOW')
        reply = self._compile(ident, owner, window, period, parts, env)
        return reply

    def _compile(self, ident, owner, window, period, parts, env):
        s, e = window
        witness = self._fit_witness(window, env)
        base = {'id': ident, 'owner': owner, 'window': window, 'env': env,
                'parts': parts, 'period': period}
        if witness is not None:
            l, t, u, c = witness
            self.preps[ident] = dict(key=self.preps_key(owner, window, period, parts, env),
                                     outcome='denied', base_rev=self.rev, **base)
            return {'status': 'denied', 'id': ident, 'rev': self.rev,
                    'kind': 'capacity', 'link': l, 'time': t, 'used': u,
                    'capacity': c}
        job = compiler.Job(self.n, self.links, parts, period, env)
        cut = find_deficient_cut(job)
        if cut is not None:
            self.preps[ident] = dict(key=self.preps_key(owner, window, period, parts, env),
                                     outcome='denied', base_rev=self.rev, **base)
            return {'status': 'denied', 'id': ident, 'rev': self.rev,
                    'kind': 'cut', 'cut': sorted(cut)}
        plan = compiler.compile_plan(job)
        self.preps[ident] = dict(key=self.preps_key(owner, window, period, parts, env),
                                 outcome='prepared' if plan is not None else 'denied',
                                 base_rev=self.rev, **base)
        if plan is not None:
            return {'status': 'prepared', 'id': ident, 'rev': self.rev, 'plan': plan}
        # No plan could be constructed although the published cut condition
        # holds; report the closest cut witness so the reply stays checkable.
        best = _closest_cut(job)
        return {'status': 'denied', 'id': ident, 'rev': self.rev,
                'kind': 'cut', 'cut': best}

    def preps_key(self, owner, window, period, parts, env):
        return (owner, window, period, frozenset(parts.items()),
                frozenset(env.items()))

    def _fit_witness(self, window, env):
        s, e = window
        points = {s}
        for rec in self.leases.values():
            if s < rec['s'] < e:
                points.add(rec['s'])
            if s < rec['e'] < e:
                points.add(rec['e'])
        for t in sorted(points):
            vec = self.used_vector(t)
            for l in range(len(self.links)):
                total = vec[l] + env.get(l, 0)
                if total > self.cap[l]:
                    return (l, t, total, self.cap[l])
        return None

    def op_commit(self, request):
        _fields(request, ('op', 'id', 'owner', 'rev'))
        ident = _name(request['id'])
        owner = _name(request['owner'])
        rev = _int(request['rev'])
        if not self.loaded:
            return self._not_loaded()
        rec = self.leases.get(ident)
        prep = self.preps.get(ident)
        if rec is None and ident not in self.dead and prep is None:
            return self._error('MISSING')
        holder = rec or prep
        known_owner = self.dead.get(ident) if (rec is None and ident in self.dead) else None
        known_owner = known_owner if known_owner is not None else holder['owner']
        if known_owner != owner:
            return self._error('OWNER')
        if rec is not None:
            return {'status': 'ok', 'id': ident, 'rev': self.rev, 'replay': True}
        if ident in self.dead:
            return self._error('GONE')
        if prep['outcome'] == 'denied':
            return self._error('DENIED')
        if rev != self.rev or prep['base_rev'] != self.rev:
            return self._stale()
        s, e = prep['window']
        self.leases[ident] = {'owner': owner, 's': s, 'e': e,
                              'env': dict(prep['env'])}
        self.rev += 1
        return {'status': 'ok', 'id': ident, 'rev': self.rev, 'replay': False}

    def op_cancel(self, request):
        _fields(request, ('op', 'id', 'owner', 'rev'))
        ident = _name(request['id'])
        owner = _name(request['owner'])
        rev = _int(request['rev'])
        if not self.loaded:
            return self._not_loaded()
        if rev != self.rev:
            return self._stale()
        rec = self.leases.get(ident)
        if rec is None:
            return self._error('MISSING')
        if rec['owner'] != owner:
            return self._error('OWNER')
        self.leases.pop(ident)
        self.dead[ident] = owner
        self.rev += 1
        return {'status': 'ok', 'rev': self.rev, 'released': ident}


def _closest_cut(job):
    C = job.C
    best = None
    bestval = None
    for k in range(1, len(C)):
        S = C[:k]
        cap, dem = compiler.cut_value(job, S)
        val = cap - dem
        if bestval is None or val < bestval:
            bestval = val
            best = S
    if best is None:
        best = [C[0]]
    return sorted(best)


def _missing():
    raise Invalid()
